let _id = 1;
const tagNameRegex = new RegExp('[^a-z0-9-_:]');

export const IGNORED_NODE = -2;

export function genId(): number {
  return _id++;
}

function getValidTagName(element: Element): Lowercase<string> {
  if (element instanceof HTMLFormElement) {
    return 'form';
  }

  const processedTagName = toLowerCase(element.tagName);

  if (tagNameRegex.test(processedTagName)) {
    // if the tag name is odd and we cannot extract
    // anything from the string, then we return a
    // generic div
    return 'div';
  }

  return processedTagName;
}

let canvasService: HTMLCanvasElement | null;
let canvasCtx: CanvasRenderingContext2D | null;

// a tainted canvas fails on every snapshot, so warn once rather than on each one
let taintedCanvasWarned = false;
function warnCanvasUnreadable(error: unknown): void {
  // only a cross-origin taint throws SecurityError. Anything else is unexpected,
  // so log it every time like the img inline path does, rather than blaming taint
  if ((error as { name?: string } | null)?.name !== 'SecurityError') {
    console.warn(
      'Cannot read canvas pixels, so this canvas is left out of the recording.',
      error,
    );
    return;
  }
  if (taintedCanvasWarned) return;
  taintedCanvasWarned = true;
  console.warn(
    'Cannot read canvas pixels, so this canvas is left out of the recording. A cross-origin image or video drawn into it taints it.',
    error,
  );
}

// oxlint-disable-next-line no-control-regex
const SRCSET_NOT_SPACES = /^[^ \t\n\r\u000c]+/; // Don't use \s, to avoid matching non-breaking space
// oxlint-disable-next-line no-control-regex
const SRCSET_COMMAS_OR_SPACES = /^[, \t\n\r\u000c]+/;

function getAbsoluteSrcsetString(doc: Document, attributeValue: string) {
  /*
    run absoluteToDoc over every url in the srcset

    this is adapted from https://github.com/albell/parse-srcset/
    without the parsing of the descriptors (we return these as-is)
    parce-srcset is in turn based on
    https://html.spec.whatwg.org/multipage/embedded-content.html#parse-a-srcset-attribute
  */
  if (attributeValue.trim() === '') {
    return attributeValue;
  }

  let pos = 0;

  function collectCharacters(regEx: RegExp) {
    let chars: string;
    const match = regEx.exec(attributeValue.substring(pos));
    if (match) {
      chars = match[0];
      pos += chars.length;
      return chars;
    }
    return '';
  }

  const output = [];
  while (true) {
    collectCharacters(SRCSET_COMMAS_OR_SPACES);
    if (pos >= attributeValue.length) {
      break;
    }
    // don't split on commas within urls
    let url = collectCharacters(SRCSET_NOT_SPACES);
    if (url.slice(-1) === ',') {
      // aside: according to spec more than one comma at the end is a parse error, but we ignore that
      url = absoluteToDoc(doc, url.substring(0, url.length - 1));
      // the trailing comma splits the srcset, so the interpretion is that
      // another url will follow, and the descriptor is empty
      output.push(url);
    } else {
      let descriptorsStr = '';
      url = absoluteToDoc(doc, url);
      let inParens = false;
      while (true) {
        const c = attributeValue.charAt(pos);
        if (c === '') {
          output.push((url + descriptorsStr).trim());
          break;
        } else if (!inParens) {
          if (c === ',') {
            pos += 1;
            output.push((url + descriptorsStr).trim());
            break; // parse the next url
          } else if (c === '(') {
            inParens = true;
          }
        } else {
          // in parenthesis; ignore commas
          // (parenthesis may be supported by future additions to spec)
          if (c === ')') {
            inParens = false;
          }
        }
        descriptorsStr += c;
        pos += 1;
      }
    }
  }
  return output.join(', ');
}

const cachedDocument = new WeakMap<Document, HTMLAnchorElement>();

export function absoluteToDoc(doc: Document, attributeValue: string): string {
  if (!attributeValue || attributeValue.trim() === '') {
    return attributeValue;
  }

  return getHref(doc, attributeValue);
}

function isSVGElement(el: Element): boolean {
  return Boolean(el.tagName === 'svg' || (el as SVGElement).ownerSVGElement);
}

function getHref(doc: Document, customHref?: string) {
  let a = cachedDocument.get(doc);
  if (!a) {
    a = doc.createElement('a');
    cachedDocument.set(doc, a);
  }
  if (!customHref) {
    customHref = '';
  } else if (customHref.startsWith('blob:') || customHref.startsWith('data:')) {
    return customHref;
  }
  // note: using `new URL` is slower. See #1434 or https://jsbench.me/uqlud17rxo/1
  // codeql[js/xss-through-dom] Detached <a>; only used to resolve URLs via the .href getter.
  a.setAttribute('href', customHref);
  return a.href;
}

function capDataURLSize(
  dataURL: string,
  dataURLOptions?: DataURLOptions,
): string {
  if (dataURLOptions?.maxBase64ImageLength) {
    return checkDataURLSize(dataURL, dataURLOptions.maxBase64ImageLength);
  }
  return dataURL;
}

export function transformAttribute(
  doc: Document,
  tagName: Lowercase<string>,
  name: Lowercase<string>,
  value: string | null,
  element?: Element,
  dataURLOptions?: DataURLOptions,
): string | null {
  if (!value) {
    return value;
  }

  // relative path in attribute
  if (
    name === 'src' ||
    (name === 'href' && !(tagName === 'use' && value[0] === '#'))
  ) {
    // Prefer the loaded sheet's href — survives baseURI changes from SPA pushState.
    if (tagName === 'link' && element) {
      const sheetHref = (element as HTMLLinkElement).sheet?.href;
      if (sheetHref) {
        return sheetHref;
      }
    }
    // href starts with a # is an id pointer for svg
    const transformedValue = absoluteToDoc(doc, value);

    if (transformedValue.startsWith('data:')) {
      if (tagName === 'img' && element) {
        let processedDataURL = transformedValue;

        if (dataURLOptions?.type || dataURLOptions?.quality !== undefined) {
          processedDataURL = recompressBase64Image(
            element as HTMLImageElement,
            transformedValue,
            dataURLOptions.type,
            dataURLOptions.quality,
          );
        }

        return capDataURLSize(processedDataURL, dataURLOptions);
      }

      if (tagName === 'image') {
        return capDataURLSize(transformedValue, dataURLOptions);
      }
    }

    return transformedValue;
  } else if (name === 'xlink:href' && value[0] !== '#') {
    // xlink:href starts with # is an id pointer
    const transformedValue = absoluteToDoc(doc, value);
    if (tagName === 'image' && transformedValue.startsWith('data:')) {
      return capDataURLSize(transformedValue, dataURLOptions);
    }
    return transformedValue;
  } else if (
    name === 'background' &&
    (tagName === 'table' || tagName === 'td' || tagName === 'th')
  ) {
    return absoluteToDoc(doc, value);
  } else if (name === 'srcset') {
    return getAbsoluteSrcsetString(doc, value);
  } else if (name === 'style') {
    return absolutifyURLs(value, getHref(doc));
  } else if (tagName === 'object' && name === 'data') {
    return absoluteToDoc(doc, value);
  }

  return value;
}

export function ignoreAttribute(
  tagName: Lowercase<string>,
  name: string,
  _value: unknown,
): boolean {
  return (
    (tagName === 'video' || tagName === 'audio') &&
    toLowerCase(name) === 'autoplay'
  );
}

/**
 * Whether a `<link>`'s `rel` marks it as a stylesheet, matching `rel` as the
 * space-separated, ASCII-case-insensitive token list it is. The distinction
 * matters because `<link rel=preload as=style>` carries the same URL as the
 * stylesheet it preloads while applying no CSS of its own.
 */
function isStylesheetLink(rel: unknown): boolean {
  if (typeof rel !== 'string') {
    return false;
  }
  return toLowerCase(rel).split(/\s+/).includes('stylesheet');
}

export function _isBlockedElement(
  element: Element,
  blockClass: string | RegExp,
  blockSelector: string | null,
): boolean {
  try {
    if (typeof blockClass === 'string') {
      if (element.classList.contains(blockClass)) {
        return true;
      }
    } else {
      for (let eIndex = element.classList.length; eIndex--; ) {
        const className = element.classList[eIndex];
        if (blockClass.test(className)) {
          return true;
        }
      }
    }
    if (blockSelector) {
      return element.matches(blockSelector);
    }
  } catch (e) {
    //
  }

  return false;
}

export function classMatchesRegex(
  node: Node | null,
  regex: RegExp,
  checkAncestors: boolean,
): boolean {
  if (!node) return false;
  if (node.nodeType !== node.ELEMENT_NODE) {
    if (!checkAncestors) return false;
    return classMatchesRegex(dom.parentNode(node), regex, checkAncestors);
  }

  for (let eIndex = (node as HTMLElement).classList.length; eIndex--; ) {
    const className = (node as HTMLElement).classList[eIndex];
    if (regex.test(className)) {
      return true;
    }
  }
  if (!checkAncestors) return false;
  return classMatchesRegex(dom.parentNode(node), regex, checkAncestors);
}

export function needMaskingText(
  node: Node,
  maskTextClass: string | RegExp,
  maskTextSelector: string | null,
  checkAncestors: boolean,
): boolean {
  let el: Element;
  if (isElement(node)) {
    el = node;
    if (!dom.childNodes(el).length) {
      // optimisation: we can avoid any of the below checks on leaf elements
      // as masking is applied to child text nodes only
      return false;
    }
  } else if (dom.parentElement(node) === null) {
    // should warn? maybe a text node isn't attached to a parent node yet?
    return false;
  } else {
    el = dom.parentElement(node)!;
  }
  try {
    if (typeof maskTextClass === 'string') {
      if (checkAncestors) {
        if (el.closest(`.${maskTextClass}`)) return true;
      } else {
        if (el.classList.contains(maskTextClass)) return true;
      }
    } else {
      if (classMatchesRegex(el, maskTextClass, checkAncestors)) return true;
    }
    if (maskTextSelector) {
      if (checkAncestors) {
        if (el.closest(maskTextSelector)) return true;
      } else {
        if (el.matches(maskTextSelector)) return true;
      }
    }
  } catch (e) {
    //
  }
  return false;
}

// Returns a disposer that removes the load listener and clears any pending
// timer — call it if the iframe is detached before the listener fires.
// https://stackoverflow.com/a/36155560
function removeEventListenerSafely(
  target: Pick<EventTarget, 'removeEventListener'>,
  type: string,
  listener: EventListenerOrEventListenerObject,
): void {
  const removeEventListener = target.removeEventListener;
  if (typeof removeEventListener !== 'function') return;
  removeEventListener.call(target, type, listener);
}

function onceIframeLoaded(
  iframeEl: HTMLIFrameElement,
  listener: () => unknown,
  iframeLoadTimeout: number,
): () => void {
  const noop = () => {};
  const win = iframeEl.contentWindow;
  if (!win) {
    return noop;
  }
  let readyState: DocumentReadyState;
  try {
    readyState = win.document.readyState;
  } catch (error) {
    return noop;
  }

  // Re-fire on any later load so iframe.src navigations get their fresh
  // contentDocument serialized too. Used by both branches below.
  const onSubsequentLoad = () => listener();

  if (readyState !== 'complete') {
    let fired = false;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const fireOnce = () => {
      if (fired) return;
      fired = true;
      if (timer !== null) {
        clearTimeout(timer);
        timer = null;
      }
      removeEventListenerSafely(iframeEl, 'load', onInitialLoad);
      iframeEl.addEventListener('load', onSubsequentLoad);
      listener();
    };
    const onInitialLoad = () => fireOnce();
    timer = setTimeout(fireOnce, iframeLoadTimeout);
    iframeEl.addEventListener('load', onInitialLoad);
    return () => {
      if (timer !== null) {
        clearTimeout(timer);
        timer = null;
      }
      if (fired) {
        removeEventListenerSafely(iframeEl, 'load', onSubsequentLoad);
      } else {
        fired = true;
        removeEventListenerSafely(iframeEl, 'load', onInitialLoad);
      }
    };
  }

  // readyState === 'complete' but Chrome reports about:blank during the
  // initial transition to a non-blank src; serializing now would emit the
  // blank doc and re-emit when the real load completes.
  const blankUrl = 'about:blank';
  let winLocationHref: string;
  try {
    winLocationHref = win.location.href;
  } catch {
    return noop;
  }
  if (
    winLocationHref !== blankUrl ||
    iframeEl.src === blankUrl ||
    iframeEl.src === ''
  ) {
    // Genuinely loaded — fire on the next tick so the host mutation that
    // surfaced this iframe has time to commit; also re-fire on later loads.
    const initialTimer = setTimeout(listener, 0);
    iframeEl.addEventListener('load', onSubsequentLoad);
    return () => {
      clearTimeout(initialTimer);
      removeEventListenerSafely(iframeEl, 'load', onSubsequentLoad);
    };
  }
  // Transient blank during navigation — wait for the real load.
  iframeEl.addEventListener('load', onSubsequentLoad);
  return () => {
    removeEventListenerSafely(iframeEl, 'load', onSubsequentLoad);
  };
}

const stylesheetLoadTracked = new Map<HTMLLinkElement, AbortController>();

export function resetStylesheetLoadTracking(): void {
  stylesheetLoadTracked.forEach((controller) => controller.abort());
  stylesheetLoadTracked.clear();
}

function onceStylesheetLoaded(
  link: HTMLLinkElement,
  listener: () => unknown,
  styleSheetLoadTimeout: number,
) {
  if (stylesheetLoadTracked.has(link)) return;

  let styleSheetLoaded: StyleSheet | null;
  try {
    styleSheetLoaded = link.sheet;
  } catch (error) {
    return;
  }

  if (styleSheetLoaded) return;

  const controller = new AbortController();
  let fired = false;
  const fire = () => {
    if (fired) return;
    fired = true;
    try {
      listener();
    } finally {
      stylesheetLoadTracked.delete(link);
      controller.abort();
    }
  };

  const timer = setTimeout(fire, styleSheetLoadTimeout);
  controller.signal.addEventListener('abort', () => clearTimeout(timer), {
    once: true,
  });
  link.addEventListener('load', fire, {
    signal: controller.signal,
    once: true,
  });

  stylesheetLoadTracked.set(link, controller);
}

function serializeNode(
  n: Node,
  options: {
    doc: Document;
    mirror: Mirror;
    blockClass: string | RegExp;
    blockSelector: string | null;
    needsMask: boolean;
    inlineStylesheet: boolean;
    maskInputOptions: MaskInputOptions;
    maskTextFn: MaskTextFn | undefined;
    maskInputFn: MaskInputFn | undefined;
    maskAllElementAttributes: boolean;
    maskAttributeFn: MaskAttributeFn | undefined;
    dataURLOptions?: DataURLOptions;
    inlineImages: boolean;
    recordCanvas: boolean;
    canvasMaskingConfigured: (() => boolean) | undefined;
    keepIframeSrcFn: KeepIframeSrcFn;
    /**
     * `newlyAddedElement: true` skips scrollTop and scrollLeft check
     */
    newlyAddedElement?: boolean;
  },
): serializedNode | false {
  const {
    doc,
    mirror,
    blockClass,
    blockSelector,
    needsMask,
    inlineStylesheet,
    maskInputOptions = {},
    maskTextFn,
    maskInputFn,
    maskAllElementAttributes = false,
    maskAttributeFn,
    dataURLOptions = {},
    inlineImages,
    recordCanvas,
    canvasMaskingConfigured,
    keepIframeSrcFn,
    newlyAddedElement = false,
  } = options;
  // Only record root id when document object is not the base document
  const rootId = getRootId(doc, mirror);
  switch (n.nodeType) {
    case n.DOCUMENT_NODE:
      if ((n as Document).compatMode !== 'CSS1Compat') {
        return {
          type: NodeType.Document,
          childNodes: [],
          compatMode: (n as Document).compatMode, // probably "BackCompat"
        };
      } else {
        return {
          type: NodeType.Document,
          childNodes: [],
        };
      }
    case n.DOCUMENT_TYPE_NODE:
      return {
        type: NodeType.DocumentType,
        name: (n as DocumentType).name,
        publicId: (n as DocumentType).publicId,
        systemId: (n as DocumentType).systemId,
        rootId,
      };
    case n.ELEMENT_NODE:
      return serializeElementNode(n as Element, {
        doc,
        blockClass,
        blockSelector,
        inlineStylesheet,
        maskInputOptions,
        maskInputFn,
        maskAllElementAttributes,
        maskAttributeFn,
        dataURLOptions,
        inlineImages,
        recordCanvas,
        canvasMaskingConfigured,
        keepIframeSrcFn,
        newlyAddedElement,
        rootId,
      });
    case n.TEXT_NODE:
      return serializeTextNode(n as Text, {
        doc,
        needsMask,
        maskTextFn,
        rootId,
      });
    case n.CDATA_SECTION_NODE:
      return {
        type: NodeType.CDATA,
        textContent: '',
        rootId,
      };
    case n.COMMENT_NODE:
      return {
        type: NodeType.Comment,
        textContent: dom.textContent(n as Comment) || '',
        rootId,
      };
    default:
      return false;
  }
}

function getRootId(doc: Document, mirror: Mirror): number | undefined {
  if (!mirror.hasNode(doc)) return undefined;
  const docId = mirror.getId(doc);
  return docId === 1 ? undefined : docId;
}

function serializeTextNode(
  n: Text,
  options: {
    doc: Document;
    needsMask: boolean;
    maskTextFn: MaskTextFn | undefined;
    rootId: number | undefined;
  },
): serializedNode {
  const { needsMask, maskTextFn, rootId } = options;
  // The parent node may not be a html element which has a tagName attribute.
  // So just let it be undefined which is ok in this use case.
  const parent = dom.parentNode(n);
  const parentTagName = parent && (parent as HTMLElement).tagName;
  let text = dom.textContent(n);
  const isStyle = parentTagName === 'STYLE' ? true : undefined;
  const isScript = parentTagName === 'SCRIPT' ? true : undefined;
  if (isStyle && text) {
    try {
      // try to read style sheet
      if (n.nextSibling || n.previousSibling) {
        // This is not the only child of the stylesheet.
        // We can't read all of the sheet's .cssRules and expect them
        // to _only_ include the current rule(s) added by the text node.
        // So we'll be conservative and keep textContent as-is.
      } else if (
        shouldDeferStylesheetInlining((parent as HTMLStyleElement).sheet)
      ) {
        // Budget spent - keep the raw textContent, which is what we already fall
        // back to for sheets we can't read. Costs us `@import` expansion and the
        // browser's rule normalisation, not the CSS itself.
      } else if ((parent as HTMLStyleElement).sheet?.cssRules) {
        const stringified = stringifyStylesheet(
          (parent as HTMLStyleElement).sheet!,
        );
        // Browsers serialize shorthand-with-var() as empty longhands, which
        // silently drops layout rules on replay. Keep the original textContent
        // when stringifyStylesheet would emit that corruption.
        if (stringified && !hasEmptyShorthandLonghand(stringified)) {
          text = stringified;
        }
      }
    } catch (err) {
      console.warn(
        `Cannot get CSS styles from text's parentNode. Error: ${err as string}`,
        n,
      );
    }
    text = absolutifyURLs(text, getHref(options.doc));
  }
  if (isScript) {
    text = SCRIPT_PLACEHOLDER;
  }
  if (!isStyle && !isScript && text && needsMask) {
    text = maskTextFn
      ? maskTextFn(text, dom.parentElement(n))
      : text.replace(/[\S]/g, '*');
  }

  return {
    type: NodeType.Text,
    textContent: text || '',
    isStyle,
    rootId,
  };
}

function findStylesheet(doc: Document, href: string) {
  return Array.from(doc.styleSheets).find((s) => s.href === href);
}

/**
 * in production, we've seen elements like
 * `<link type="text/css" rel="stylesheet" id="dark-mode-custom-link"></link>`
 * while HTMLLinkElement suggests an href is always present
 * the w3c spec is less specific
 * and regardless we've seen at least one instance of this in the wild
 * let's be defensive and make sure this is typed as possibly undefined
 */
function hrefFrom(n: unknown): string | undefined {
  return (n as HTMLLinkElement).href;
}

function serializeElementNode(
  n: Element,
  options: {
    doc: Document;
    blockClass: string | RegExp;
    blockSelector: string | null;
    inlineStylesheet: boolean;
    maskInputOptions: MaskInputOptions;
    maskInputFn: MaskInputFn | undefined;
    maskAllElementAttributes: boolean;
    maskAttributeFn: MaskAttributeFn | undefined;
    dataURLOptions?: DataURLOptions;
    inlineImages: boolean;
    recordCanvas: boolean;
    canvasMaskingConfigured: (() => boolean) | undefined;
    keepIframeSrcFn: KeepIframeSrcFn;
    /**
     * `newlyAddedElement: true` skips scrollTop and scrollLeft check
     */
    newlyAddedElement?: boolean;
    rootId: number | undefined;
  },
): serializedNode | false {
  const {
    doc,
    blockClass,
    blockSelector,
    inlineStylesheet,
    maskInputOptions = {},
    maskInputFn,
    maskAllElementAttributes = false,
    maskAttributeFn,
    dataURLOptions = {},
    inlineImages,
    recordCanvas,
    canvasMaskingConfigured,
    keepIframeSrcFn,
    newlyAddedElement = false,
    rootId,
  } = options;
  const needBlock = _isBlockedElement(n, blockClass, blockSelector);
  const tagName = getValidTagName(n);
  const generatedAttributeNames = new Set<string>();
  let attributes: attributes = {};
  const len = n.attributes.length;
  for (let i = 0; i < len; i++) {
    const attr = n.attributes[i];
    if (!ignoreAttribute(tagName, attr.name, attr.value)) {
      attributes[attr.name] = transformAttribute(
        doc,
        tagName,
        toLowerCase(attr.name),
        attr.value,
        n,
        dataURLOptions,
      );
    }
  }
  // remote css
  // a blocked link is serialized as a dimensions-only placeholder, so reading its
  // sheet would be wasted work - and deferring it would leak CSS the block excluded
  if (
    tagName === 'link' &&
    inlineStylesheet &&
    !needBlock &&
    // Only a real stylesheet link. `preload`/`prefetch` links carry the URL of
    // a sheet without applying it, so the href lookup below happily resolves
    // them to the loaded sheet - and then the whole stylesheet is inlined twice
    // into the snapshot, once on an element the replayer must leave alone.
    isStylesheetLink(attributes.rel)
  ) {
    // Direct sheet reference survives baseURI drift; href lookup is the fallback.
    let stylesheet: CSSStyleSheet | null | undefined = (n as HTMLLinkElement)
      .sheet;
    if (!stylesheet) {
      const href: string | undefined = hrefFrom(n);
      if (href) {
        stylesheet = findStylesheet(doc, href);
        if (!stylesheet && href.includes('.css')) {
          const rootDomain = window.location.origin;
          const stylesheetPath = href.replace(window.location.href, '');
          const potentialStylesheetHref = rootDomain + '/' + stylesheetPath;
          stylesheet = findStylesheet(doc, potentialStylesheetHref);
        }
      }
    }
    let cssText: string | null = null;
    if (stylesheet) {
      if (shouldDeferStylesheetInlining(stylesheet)) {
        // This snapshot has already spent its stylesheet budget. Leave `rel`/`href`
        // in place so the replayer can still load the sheet remotely, and hand the
        // element to the caller to inline off the critical path.
        deferStylesheetLink(n as HTMLLinkElement);
      } else {
        cssText = stringifyStylesheet(stylesheet);
      }
    }
    if (cssText) {
      delete attributes.rel;
      delete attributes.href;
      attributes._cssText = cssText;
    }
  }
  // dynamic stylesheet
  if (
    tagName === 'style' &&
    (n as HTMLStyleElement).sheet &&
    // TODO: Currently we only try to get dynamic stylesheet when it is an empty style element
    !((n as HTMLElement).innerText || dom.textContent(n) || '').trim().length
  ) {
    // a CSSOM-only sheet has no href or textContent fallback, so it can never
    // be deferred; its rules must not charge the budget either
    const cssText = runNonDeferrableStylesheetWork(() =>
      stringifyStylesheet((n as HTMLStyleElement).sheet as CSSStyleSheet),
    );
    if (cssText) {
      attributes._cssText = cssText;
    }
  }
  // form fields
  if (tagName === 'input' || tagName === 'textarea' || tagName === 'select') {
    const value = (n as HTMLInputElement | HTMLTextAreaElement).value;
    const checked = (n as HTMLInputElement).checked;
    if (
      attributes.type !== 'radio' &&
      attributes.type !== 'checkbox' &&
      attributes.type !== 'submit' &&
      attributes.type !== 'button' &&
      value
    ) {
      attributes.value = maskInputValue({
        element: n as HTMLElement,
        type: getInputType(n as HTMLElement),
        tagName,
        value,
        maskInputOptions,
        maskInputFn,
      });
    } else if (checked) {
      attributes.checked = checked;
    }
  }
  if (tagName === 'option') {
    if ((n as HTMLOptionElement).selected && !maskInputOptions['select']) {
      attributes.selected = true;
    } else {
      // ignore the html attribute (which corresponds to DOM (n as HTMLOptionElement).defaultSelected)
      // if it's already been changed
      delete attributes.selected;
    }
  }

  if (tagName === 'dialog' && (n as HTMLDialogElement).open) {
    // register what type of dialog is this
    // `modal` or `non-modal`
    // this is used to trigger `showModal()` or `show()` on replay (outside of rrweb-snapshot, in rrweb)
    try {
      (attributes as DialogAttributes).rr_open_mode = n.matches('dialog:modal')
        ? 'modal'
        : 'non-modal';
    } catch {
      // likely this is safari not able to deal with the `:modal` selector
      // we can't detect whether the dialog is modal or non-modal open, so have to guess
      // hopefully this is only safari 15.4 and 15.5
      attributes.rr_open_mode = 'modal';
      attributes.ph_rr_could_not_detect_modal = true;
    }
    generatedAttributeNames.add('rr_open_mode');
  }

  // canvas image data
  // when a canvas mask provider is configured, canvas pixels only ever reach
  // the payload through the masked frame stream — serializing them here would
  // bypass the masking
  if (tagName === 'canvas' && recordCanvas && !canvasMaskingConfigured?.()) {
    // `toDataURL` throws a SecurityError on a canvas the page tainted with a
    // cross-origin draw. This runs inside the full-snapshot serialize pass, so
    // an escaping throw costs the whole recording: no FullSnapshot event is
    // emitted and no observer is ever attached. Drop the canvas instead.
    try {
      if ((n as ICanvas).__context === '2d') {
        // only record this on 2d canvas
        if (!is2DCanvasBlank(n as HTMLCanvasElement)) {
          attributes.rr_dataURL = (n as HTMLCanvasElement).toDataURL(
            dataURLOptions.type,
            dataURLOptions.quality,
          );
        }
      } else if (!('__context' in n)) {
        // context is unknown, better not call getContext to trigger it
        const canvasDataURL = (n as HTMLCanvasElement).toDataURL(
          dataURLOptions.type,
          dataURLOptions.quality,
        );

        // create blank canvas of same dimensions
        const blankCanvas = doc.createElement('canvas');
        blankCanvas.width = (n as HTMLCanvasElement).width;
        blankCanvas.height = (n as HTMLCanvasElement).height;
        const blankCanvasDataURL = blankCanvas.toDataURL(
          dataURLOptions.type,
          dataURLOptions.quality,
        );

        // no need to save dataURL if it's the same as blank canvas
        if (canvasDataURL !== blankCanvasDataURL) {
          attributes.rr_dataURL = canvasDataURL;
        }
      }
    } catch (err) {
      warnCanvasUnreadable(err);
    }
  }
  // save image offline
  let serializationComplete = false;
  if (tagName === 'img' && inlineImages) {
    if (!canvasService) {
      canvasService = doc.createElement('canvas');
      canvasCtx = canvasService.getContext('2d');
    }
    const image = n as HTMLImageElement;
    const imageSrc: string =
      image.currentSrc || image.getAttribute('src') || '<unknown-src>';
    const priorCrossOrigin = image.crossOrigin;
    // recordInlineImage can fire after the masking pass at the end of this
    // function, in which case the values it assigns must be masked here.
    const maskLateAttribute = (name: string, value: string) =>
      serializationComplete
        ? maskAttributeValue({
            element: n,
            name,
            value,
            maskAllElementAttributes,
            maskAttributeFn,
          })
        : value;
    const recordInlineImage = () => {
      removeEventListenerSafely(image, 'load', recordInlineImage);
      try {
        canvasService!.width = image.naturalWidth;
        canvasService!.height = image.naturalHeight;
        canvasCtx!.drawImage(image, 0, 0);
        const dataURL = canvasService!.toDataURL(
          dataURLOptions.type,
          dataURLOptions.quality,
        );
        attributes.rr_dataURL = maskLateAttribute('rr_dataURL', dataURL);
      } catch (err) {
        if (image.crossOrigin !== 'anonymous') {
          image.crossOrigin = 'anonymous';
          if (image.complete && image.naturalWidth !== 0)
            recordInlineImage(); // too early due to image reload
          else image.addEventListener('load', recordInlineImage);
          return;
        } else {
          console.warn(
            `Cannot inline img src=${imageSrc}! Error: ${err as string}`,
          );
        }
      }
      if (image.crossOrigin === 'anonymous') {
        if (priorCrossOrigin) {
          attributes.crossOrigin = maskLateAttribute(
            'crossOrigin',
            priorCrossOrigin,
          );
        } else {
          image.removeAttribute('crossorigin');
        }
      }
    };
    // The image content may not have finished loading yet.
    if (image.complete && image.naturalWidth !== 0) recordInlineImage();
    else image.addEventListener('load', recordInlineImage);
  }
  // media elements
  if (tagName === 'audio' || tagName === 'video') {
    const mediaAttributes = attributes as mediaAttributes;
    mediaAttributes.rr_mediaState = (n as HTMLMediaElement).paused
      ? 'paused'
      : 'played';
    generatedAttributeNames.add('rr_mediaState');
    mediaAttributes.rr_mediaCurrentTime = (n as HTMLMediaElement).currentTime;
    mediaAttributes.rr_mediaPlaybackRate = (n as HTMLMediaElement).playbackRate;
    mediaAttributes.rr_mediaMuted = (n as HTMLMediaElement).muted;
    mediaAttributes.rr_mediaLoop = (n as HTMLMediaElement).loop;
    mediaAttributes.rr_mediaVolume = (n as HTMLMediaElement).volume;
  }
  // Scroll
  if (!newlyAddedElement) {
    // `scrollTop` and `scrollLeft` are expensive calls because they trigger reflow.
    // Since `scrollTop` & `scrollLeft` are always 0 when an element is added to the DOM.
    // And scrolls also get picked up by rrweb's ScrollObserver
    // So we can safely skip the `scrollTop/Left` calls for newly added elements
    if (n.scrollLeft) {
      attributes.rr_scrollLeft = n.scrollLeft;
    }
    if (n.scrollTop) {
      attributes.rr_scrollTop = n.scrollTop;
    }
  }
  // block element
  if (needBlock) {
    const { width, height, left, top } = n.getBoundingClientRect();
    const computed = doc.defaultView?.getComputedStyle(n);
    attributes = {
      class: attributes.class,
      rr_width: `${width}px`,
      rr_height: `${height}px`,
      rr_left: `${Math.floor(left + (doc.defaultView?.scrollX || 0))}px`,
      rr_top: `${Math.floor(top + (doc.defaultView?.scrollY || 0))}px`,
    };
    generatedAttributeNames.add('rr_width');
    generatedAttributeNames.add('rr_height');
    generatedAttributeNames.add('rr_left');
    generatedAttributeNames.add('rr_top');
    // Captured so rebuild can keep originally-in-flow placeholders in flow
    // instead of forcing `position: absolute` and collapsing sibling layout.
    if (computed) {
      // JSDOM-style envs return '' for unset computed values; normalize to the CSS default.
      attributes.rr_position = computed.position || 'static';
      generatedAttributeNames.add('rr_position');
      if (computed.transform && computed.transform !== 'none') {
        attributes.rr_transform = computed.transform;
        generatedAttributeNames.add('rr_transform');
      }
      // Any inline-level box has its in-flow slot rebuilt as the tag's default
      // display once style is stripped, which collapses width/height. Capture
      // so rebuild can restore (promote plain `inline` → `inline-block`).
      if (computed.display && computed.display.startsWith('inline')) {
        attributes.rr_display = computed.display;
        generatedAttributeNames.add('rr_display');
      }
    }
  }
  // iframe
  if (tagName === 'iframe' && !keepIframeSrcFn(attributes.src as string)) {
    if (!(n as HTMLIFrameElement).contentDocument) {
      // we can't record it directly as we can't see into it
      // preserve the src attribute so a decision can be taken at replay time
      attributes.rr_src = attributes.src;
    }
    delete attributes.src; // prevent auto loading
  }

  // Mask the final serialized representation after synthesized values and
  // rrweb keys have been applied, so later serialization cannot restore PII.
  if (maskAllElementAttributes || maskAttributeFn) {
    for (const [name, value] of Object.entries(attributes)) {
      if (typeof value === 'string' || value === null) {
        attributes[name] = maskAttributeValue({
          element: n,
          name,
          value,
          maskAllElementAttributes,
          maskAttributeFn,
          isGenerated: generatedAttributeNames.has(name),
        });
      }
    }
  }
  serializationComplete = true;

  let isCustomElement: true | undefined;
  try {
    if (customElements.get(tagName)) isCustomElement = true;
  } catch (e) {
    // In case old browsers don't support customElements
  }

  return {
    type: NodeType.Element,
    tagName,
    attributes,
    childNodes: [],
    isSVG: isSVGElement(n as Element) || undefined,
    needBlock,
    rootId,
    isCustom: isCustomElement,
  };
}

function lowerIfExists(
  maybeAttr: string | number | boolean | undefined | null,
): string {
  if (maybeAttr === undefined || maybeAttr === null) {
    return '';
  } else {
    return (maybeAttr as string).toLowerCase();
  }
}

function slimDOMExcluded(
  sn: serializedNode,
  slimDOMOptions: SlimDOMOptions,
): boolean {
  if (slimDOMOptions.comment && sn.type === NodeType.Comment) {
    // TODO: convert IE conditional comments to real nodes
    return true;
  } else if (sn.type === NodeType.Element) {
    if (
      slimDOMOptions.script &&
      // script tag
      (sn.tagName === 'script' ||
        // (module)preload link
        (sn.tagName === 'link' &&
          ((sn.attributes.rel === 'preload' && sn.attributes.as === 'script') ||
            sn.attributes.rel === 'modulepreload')) ||
        // prefetch link
        (sn.tagName === 'link' &&
          sn.attributes.rel === 'prefetch' &&
          typeof sn.attributes.href === 'string' &&
          extractFileExtension(sn.attributes.href) === 'js'))
    ) {
      return true;
    } else if (
      slimDOMOptions.headFavicon &&
      ((sn.tagName === 'link' && sn.attributes.rel === 'shortcut icon') ||
        (sn.tagName === 'meta' &&
          (lowerIfExists(sn.attributes.name).match(
            /^msapplication-tile(image|color)$/,
          ) ||
            lowerIfExists(sn.attributes.name) === 'application-name' ||
            ['icon', 'apple-touch-icon', 'shortcut icon'].includes(
              lowerIfExists(sn.attributes.rel),
            ))))
    ) {
      return true;
    } else if (sn.tagName === 'meta') {
      if (
        slimDOMOptions.headMetaDescKeywords &&
        lowerIfExists(sn.attributes.name).match(/^description|keywords$/)
      ) {
        return true;
      } else if (
        slimDOMOptions.headMetaSocial &&
        (lowerIfExists(sn.attributes.property).match(/^(og|twitter|fb):/) || // og = opengraph (facebook)
          lowerIfExists(sn.attributes.name).match(/^(og|twitter):/) ||
          lowerIfExists(sn.attributes.name) === 'pinterest')
      ) {
        return true;
      } else if (
        slimDOMOptions.headMetaRobots &&
        ['robots', 'googlebot', 'bingbot'].includes(
          lowerIfExists(sn.attributes.name),
        )
      ) {
        return true;
      } else if (
        slimDOMOptions.headMetaHttpEquiv &&
        sn.attributes['http-equiv'] !== undefined
      ) {
        // e.g. X-UA-Compatible, Content-Type, Content-Language,
        // cache-control, X-Translated-By
        return true;
      } else if (
        slimDOMOptions.headMetaAuthorship &&
        (['author', 'generator', 'framework', 'publisher', 'progid'].includes(
          lowerIfExists(sn.attributes.name),
        ) ||
          lowerIfExists(sn.attributes.property).match(/^article:/) ||
          lowerIfExists(sn.attributes.property).match(/^product:/))
      ) {
        return true;
      } else if (
        slimDOMOptions.headMetaVerification &&
        [
          'google-site-verification',
          'yandex-verification',
          'csrf-token',
          'p:domain_verify',
          'verify-v1',
          'verification',
          'shopify-checkout-api-token',
        ].includes(lowerIfExists(sn.attributes.name))
      ) {
        return true;
      }
    }
  }
  return false;
}

export const DEFAULT_MAX_DEPTH = 50;

let _maxDepthWarned = false;
let _maxDepthReached = false;

export function wasMaxDepthReached(): boolean {
  return _maxDepthReached;
}

export function resetMaxDepthState(): void {
  _maxDepthReached = false;
  _maxDepthWarned = false;
}

export function serializeNodeWithId(
  n: Node,
  options: {
    doc: Document;
    mirror: Mirror;
    blockClass: string | RegExp;
    blockSelector: string | null;
    maskTextClass: string | RegExp;
    maskTextSelector: string | null;
    skipChild: boolean;
    inlineStylesheet: boolean;
    newlyAddedElement?: boolean;
    maskInputOptions?: MaskInputOptions;
    needsMask?: boolean;
    maskTextFn: MaskTextFn | undefined;
    maskInputFn: MaskInputFn | undefined;
    maskAllElementAttributes?: boolean;
    maskAttributeFn?: MaskAttributeFn;
    slimDOMOptions: SlimDOMOptions;
    dataURLOptions?: DataURLOptions;
    keepIframeSrcFn?: KeepIframeSrcFn;
    inlineImages?: boolean;
    recordCanvas?: boolean;
    canvasMaskingConfigured?: () => boolean;
    preserveWhiteSpace?: boolean;
    onSerialize?: (n: Node) => unknown;
    onIframeLoad?: (
      iframeNode: HTMLIFrameElement,
      node: serializedElementNodeWithId,
    ) => unknown;
    iframeLoadTimeout?: number;
    onIframeListenerRegistered?: (
      iframeNode: HTMLIFrameElement,
      disposer: () => void,
    ) => void;
    onStylesheetLoad?: (
      linkNode: HTMLLinkElement,
      node: serializedElementNodeWithId,
    ) => unknown;
    stylesheetLoadTimeout?: number;
    depth?: number;
    maxDepth?: number;
    onMaxDepthReached?: () => void;
  },
): serializedNodeWithId | null {
  const {
    doc,
    mirror,
    blockClass,
    blockSelector,
    maskTextClass,
    maskTextSelector,
    skipChild = false,
    inlineStylesheet = true,
    maskInputOptions = {},
    maskTextFn,
    maskInputFn,
    maskAllElementAttributes = false,
    maskAttributeFn,
    slimDOMOptions,
    dataURLOptions = {},
    inlineImages = false,
    recordCanvas = false,
    canvasMaskingConfigured,
    onSerialize,
    onIframeLoad,
    iframeLoadTimeout = 5000,
    onIframeListenerRegistered,
    onStylesheetLoad,
    stylesheetLoadTimeout = 5000,
    keepIframeSrcFn = () => false,
    newlyAddedElement = false,
    depth = 0,
    maxDepth = DEFAULT_MAX_DEPTH,
  } = options;
  let { needsMask } = options;
  let { preserveWhiteSpace = true } = options;

  if (depth >= maxDepth) {
    _maxDepthReached = true;
    if (!_maxDepthWarned) {
      _maxDepthWarned = true;
      console.warn(
        `[rrweb-snapshot] DOM tree depth exceeded max depth of ${maxDepth}. ` +
          `Children beyond this depth will not be recorded. ` +
          `This may indicate deeply nested DOM structures.`,
      );
    }
    return null;
  }

  if (!needsMask) {
    // perf: if needsMask = true, children won't also need to check
    const checkAncestors = needsMask === undefined; // if false, we've already checked ancestors
    needsMask = needMaskingText(
      n as Element,
      maskTextClass,
      maskTextSelector,
      checkAncestors,
    );
  }

  countSerializedNode();

  const _serializedNode = serializeNode(n, {
    doc,
    mirror,
    blockClass,
    blockSelector,
    needsMask,
    inlineStylesheet,
    maskInputOptions,
    maskTextFn,
    maskInputFn,
    maskAllElementAttributes,
    maskAttributeFn,
    dataURLOptions,
    inlineImages,
    recordCanvas,
    canvasMaskingConfigured,
    keepIframeSrcFn,
    newlyAddedElement,
  });
  if (!_serializedNode) {
    // TODO: dev only
    console.warn(n, 'not serialized');
    return null;
  }

  let id: number | undefined;
  if (mirror.hasNode(n)) {
    // Reuse the previous id
    id = mirror.getId(n);
  } else if (
    slimDOMExcluded(_serializedNode, slimDOMOptions) ||
    (!preserveWhiteSpace &&
      _serializedNode.type === NodeType.Text &&
      !_serializedNode.isStyle &&
      // codeql[js/polynomial-redos] Bounded DOM text node; worst case is recorder slowdown, no exploit.
      !_serializedNode.textContent.replace(/^\s+|\s+$/gm, '').length)
  ) {
    id = IGNORED_NODE;
  } else {
    id = genId();
  }

  const serializedNode = Object.assign(_serializedNode, { id });
  // add IGNORED_NODE to mirror to track nextSiblings
  mirror.add(n, serializedNode);

  if (id === IGNORED_NODE) {
    return null; // slimDOM
  }

  if (onSerialize) {
    onSerialize(n);
  }
  let recordChild = !skipChild;
  if (serializedNode.type === NodeType.Element) {
    recordChild = recordChild && !serializedNode.needBlock;
    // this property was not needed in replay side
    delete serializedNode.needBlock;
    const shadowRootEl = dom.shadowRoot(n);
    if (shadowRootEl && isNativeShadowDom(shadowRootEl))
      serializedNode.isShadowHost = true;
  }
  if (
    (serializedNode.type === NodeType.Document ||
      serializedNode.type === NodeType.Element) &&
    recordChild
  ) {
    if (
      slimDOMOptions.headWhitespace &&
      serializedNode.type === NodeType.Element &&
      serializedNode.tagName === 'head'
      // would impede performance: || getComputedStyle(n)['white-space'] === 'normal'
    ) {
      preserveWhiteSpace = false;
    }
    const bypassOptions = {
      doc,
      mirror,
      blockClass,
      blockSelector,
      needsMask,
      maskTextClass,
      maskTextSelector,
      skipChild,
      inlineStylesheet,
      maskInputOptions,
      maskTextFn,
      maskInputFn,
      maskAllElementAttributes,
      maskAttributeFn,
      slimDOMOptions,
      dataURLOptions,
      inlineImages,
      recordCanvas,
      canvasMaskingConfigured,
      preserveWhiteSpace,
      onSerialize,
      onIframeLoad,
      iframeLoadTimeout,
      onIframeListenerRegistered,
      onStylesheetLoad,
      stylesheetLoadTimeout,
      keepIframeSrcFn,
      depth: depth + 1,
      maxDepth,
    };

    if (
      serializedNode.type === NodeType.Element &&
      serializedNode.tagName === 'textarea' &&
      (serializedNode as elementNode).attributes.value !== undefined
    ) {
      // value parameter in DOM reflects the correct value, so ignore childNode
    } else {
      for (const childN of Array.from(dom.childNodes(n))) {
        const serializedChildNode = serializeNodeWithId(childN, bypassOptions);
        if (serializedChildNode) {
          serializedNode.childNodes.push(serializedChildNode);
        }
      }
    }

    let shadowRootEl: ShadowRoot | null = null;
    if (isElement(n) && (shadowRootEl = dom.shadowRoot(n))) {
      for (const childN of Array.from(dom.childNodes(shadowRootEl))) {
        const serializedChildNode = serializeNodeWithId(childN, bypassOptions);
        if (serializedChildNode) {
          isNativeShadowDom(shadowRootEl) &&
            (serializedChildNode.isShadow = true);
          serializedNode.childNodes.push(serializedChildNode);
        }
      }
    }
  }

  const parent = dom.parentNode(n);
  if (parent && isShadowRoot(parent) && isNativeShadowDom(parent)) {
    serializedNode.isShadow = true;
  }

  if (
    serializedNode.type === NodeType.Element &&
    serializedNode.tagName === 'iframe'
  ) {
    const iframeDisposer = onceIframeLoaded(
      n as HTMLIFrameElement,
      () => {
        const iframeDoc = (n as HTMLIFrameElement).contentDocument;
        if (iframeDoc && onIframeLoad) {
          const serializedIframeNode = serializeNodeWithId(iframeDoc, {
            doc: iframeDoc,
            mirror,
            blockClass,
            blockSelector,
            needsMask,
            maskTextClass,
            maskTextSelector,
            skipChild: false,
            inlineStylesheet,
            maskInputOptions,
            maskTextFn,
            maskInputFn,
            maskAllElementAttributes,
            maskAttributeFn,
            slimDOMOptions,
            dataURLOptions,
            inlineImages,
            recordCanvas,
            canvasMaskingConfigured,
            preserveWhiteSpace,
            onSerialize,
            onIframeLoad,
            iframeLoadTimeout,
            onIframeListenerRegistered,
            onStylesheetLoad,
            stylesheetLoadTimeout,
            keepIframeSrcFn,
            depth: depth + 1,
            maxDepth,
          });

          if (serializedIframeNode) {
            onIframeLoad(
              n as HTMLIFrameElement,
              serializedIframeNode as serializedElementNodeWithId,
            );
          }
        }
      },
      iframeLoadTimeout,
    );
    onIframeListenerRegistered?.(n as HTMLIFrameElement, iframeDisposer);
  }

  // <link rel=stylesheet href=...>
  if (
    serializedNode.type === NodeType.Element &&
    serializedNode.tagName === 'link' &&
    isStylesheetLink(serializedNode.attributes.rel)
  ) {
    onceStylesheetLoaded(
      n as HTMLLinkElement,
      () => {
        if (onStylesheetLoad) {
          const serializedLinkNode = serializeNodeWithId(n, {
            doc,
            mirror,
            blockClass,
            blockSelector,
            needsMask,
            maskTextClass,
            maskTextSelector,
            skipChild: false,
            inlineStylesheet,
            maskInputOptions,
            maskTextFn,
            maskInputFn,
            maskAllElementAttributes,
            maskAttributeFn,
            slimDOMOptions,
            dataURLOptions,
            inlineImages,
            recordCanvas,
            canvasMaskingConfigured,
            preserveWhiteSpace,
            onSerialize,
            onIframeLoad,
            iframeLoadTimeout,
            onStylesheetLoad,
            stylesheetLoadTimeout,
            keepIframeSrcFn,
            depth,
            maxDepth,
          });

          if (serializedLinkNode) {
            onStylesheetLoad(
              n as HTMLLinkElement,
              serializedLinkNode as serializedElementNodeWithId,
            );
          }
        }
      },
      stylesheetLoadTimeout,
    );
  }

  return serializedNode;
}

export function slimDOMDefaults(
  slimDOM: 'all' | boolean | SlimDOMOptions,
): SlimDOMOptions {
  if (slimDOM === true || slimDOM === 'all') {
    return {
      script: true,
      comment: true,
      headFavicon: true,
      headWhitespace: true,
      headMetaSocial: true,
      headMetaRobots: true,
      headMetaHttpEquiv: true,
      headMetaVerification: true,
      headMetaAuthorship: slimDOM === 'all',
      headMetaDescKeywords: slimDOM === 'all',
      headTitleMutations: slimDOM === 'all',
    };
  }
  if (slimDOM === false) {
    return {};
  }
  return slimDOM;
}

function snapshot(
  n: Document,
  options?: {
    mirror?: Mirror;
    blockClass?: string | RegExp;
    blockSelector?: string | null;
    maskTextClass?: string | RegExp;
    maskTextSelector?: string | null;
    inlineStylesheet?: boolean;
    maskAllInputs?: boolean | MaskInputOptions;
    maskTextFn?: MaskTextFn;
    maskInputFn?: MaskInputFn;
    maskAllElementAttributes?: boolean;
    maskAttributeFn?: MaskAttributeFn;
    slimDOM?: 'all' | boolean | SlimDOMOptions;
    dataURLOptions?: DataURLOptions;
    inlineImages?: boolean;
    recordCanvas?: boolean;
    canvasMaskingConfigured?: () => boolean;
    preserveWhiteSpace?: boolean;
    onSerialize?: (n: Node) => unknown;
    onIframeLoad?: (
      iframeNode: HTMLIFrameElement,
      node: serializedElementNodeWithId,
    ) => unknown;
    iframeLoadTimeout?: number;
    onIframeListenerRegistered?: (
      iframeNode: HTMLIFrameElement,
      disposer: () => void,
    ) => void;
    onStylesheetLoad?: (
      linkNode: HTMLLinkElement,
      node: serializedElementNodeWithId,
    ) => unknown;
    stylesheetLoadTimeout?: number;
    keepIframeSrcFn?: KeepIframeSrcFn;
    maxDepth?: number;
    /**
     * Cap on the number of CSSRules this snapshot may stringify. Sheets past the
     * cap are left un-inlined and reported by `takeDeferredStylesheetLinks()` so
     * the caller can inline them off the critical path. Omit or pass 0 for the
     * previous unbounded behaviour.
     */
    inlineStylesheetBudgetRules?: number;
  },
): serializedNodeWithId | null {
  const {
    mirror = new Mirror(),
    blockClass = 'rr-block',
    blockSelector = null,
    maskTextClass = 'rr-mask',
    maskTextSelector = null,
    inlineStylesheet = true,
    inlineImages = false,
    recordCanvas = false,
    canvasMaskingConfigured,
    maskAllInputs = false,
    maskTextFn,
    maskInputFn,
    maskAllElementAttributes = false,
    maskAttributeFn,
    slimDOM = false,
    dataURLOptions,
    preserveWhiteSpace,
    onSerialize,
    onIframeLoad,
    iframeLoadTimeout,
    onIframeListenerRegistered,
    onStylesheetLoad,
    stylesheetLoadTimeout,
    keepIframeSrcFn = () => false,
    maxDepth,
    inlineStylesheetBudgetRules,
  } = options || {};
  const maskInputOptions: MaskInputOptions =
    maskAllInputs === true
      ? {
          color: true,
          date: true,
          'datetime-local': true,
          email: true,
          month: true,
          number: true,
          range: true,
          search: true,
          tel: true,
          text: true,
          time: true,
          url: true,
          week: true,
          textarea: true,
          select: true,
          password: true,
        }
      : maskAllInputs === false
      ? {
          password: true,
        }
      : maskAllInputs;
  const slimDOMOptions: SlimDOMOptions = slimDOMDefaults(slimDOM);
  beginSnapshotCostTracking(inlineStylesheetBudgetRules);
  try {
    return serializeNodeWithId(n, {
      doc: n,
      mirror,
      blockClass,
      blockSelector,
      maskTextClass,
      maskTextSelector,
      skipChild: false,
      inlineStylesheet,
      maskInputOptions,
      maskTextFn,
      maskInputFn,
      maskAllElementAttributes,
      maskAttributeFn,
      slimDOMOptions,
      dataURLOptions,
      inlineImages,
      recordCanvas,
      canvasMaskingConfigured,
      preserveWhiteSpace,
      onSerialize,
      onIframeLoad,
      iframeLoadTimeout,
      onIframeListenerRegistered,
      onStylesheetLoad,
      stylesheetLoadTimeout,
      keepIframeSrcFn,
      newlyAddedElement: false,
      maxDepth,
    });
  } finally {
    endSnapshotCostTracking();
  }
}

export function visitSnapshot(
  node: serializedNodeWithId,
  onVisit: (node: serializedNodeWithId) => unknown,
): void {
  function walk(current: serializedNodeWithId) {
    onVisit(current);
    if (
      current.type === NodeType.Document ||
      current.type === NodeType.Element
    ) {
      current.childNodes.forEach(walk);
    }
  }

  walk(node);
}

export function cleanupSnapshot(): void {
  // allow a new recording to start numbering nodes from scratch
  _id = 1;
}

export default snapshot;
